import{d as g,C as n,o as h,c as u,a3 as i,E as s,j as t,a as d}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"论语·子张","description":"《论语》第 19 篇「子张」——二十五章原文与导读。士见危致命、博学笃志切问近思、仕而优则学、哀矜而勿喜，弟子群像与子贡护师。","frontmatter":{"title":"论语·子张","description":"《论语》第 19 篇「子张」——二十五章原文与导读。士见危致命、博学笃志切问近思、仕而优则学、哀矜而勿喜，弟子群像与子贡护师。","category":"guide","aliases":["子张","子张篇","子张第十九","论语子张","lunyu 子张"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-19.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-19.md","lastUpdated":1790316338000}'),p={name:"lizhimingde/sishu-wujing/lunyu/chapter-19.md"},w=g({...p,setup(b){const a=[{id:"yi",label:"一、士见危致命",showLabel:!0,sentences:[["子张曰：“士见危致命，见得思义，祭思敬，丧思哀，其可已矣。”"]],note:"子张曰：「士见危致命，见得思义，祭思敬，丧思哀，其可已矣」——士见危难便致其命，见可得之利便思义，祭则思敬，丧则思哀：如此可矣。"},{id:"er",label:"二、执德不弘，信道不笃",showLabel:!0,sentences:[["子张曰：“执德不弘，信道不笃，焉能为有？焉能为亡？”"]],note:"子张曰：「执德不弘，信道不笃，焉能为有？焉能为亡（无）」——守德而不弘大，信道而不笃实，则（于世）岂足为有？又岂足为无？谓其无足轻重。"},{id:"san",label:"三、尊贤而容众",showLabel:!0,sentences:[["子夏之门人问交于子张，子张曰：“子夏云何？”对曰：“子夏曰：‘可者与之，其不可者拒之。’”子张曰：“异乎吾所闻。君子尊贤而容众，",{text:"嘉善而矜不能",glossary:"jiashanerjinneng"},"。我之大贤与，于人何所不容？我之不贤与，人将拒我，如之何其拒人也？”"]],note:"子夏之门人问交于子张。子张曰：「子夏云何」？对曰：「子夏曰：可者与之，其不可者拒之」。子张曰：「异乎吾所闻。君子尊贤而容众，嘉善而矜不能。我之大贤与，于人何所不容？我之不贤与，人将拒我，如之何其拒人也」——与我所闻不同：君子尊贤而容众，嘉善而怜不能；我若大贤，于人何所不容？我若不贤，人将拒我，我又何能拒人？"},{id:"si",label:"四、虽小道必有可观者焉",showLabel:!0,sentences:[["子夏曰：“虽小道必有可观者焉，致远恐",{text:"泥",glossary:"ni"},"，是以君子不为也。”"]],note:"子夏曰：「虽小道必有可观者焉，致远恐泥，是以君子不为也」——虽是小技艺亦有可观，然致远恐陷溺其中（泥＝陷溺），故君子不为。"},{id:"wu",label:"五、日知其所亡",showLabel:!0,sentences:[["子夏曰：“日知其所亡，月无忘其所能，可谓好学也已矣。”"]],note:"子夏曰：「日知其所亡（无），月无忘其所能，可谓好学也已矣」——日知其所未有，月不忘其所能，可谓好学。"},{id:"liu",label:"六、博学而笃志，切问而近思",showLabel:!0,sentences:[["子夏曰：“博学而笃志，",{text:"切问而近思",glossary:"qiewenjinsi"},"，仁在其中矣。”"]],note:"子夏曰：「博学而笃志，切问而近思，仁在其中矣」——博学而志向坚定，恳切发问而就切身处思索，仁便在其中。"},{id:"qi",label:"七、百工居肆以成其事",showLabel:!0,sentences:[["子夏曰：“百工居肆以成其事，君子学以致其道。”"]],note:"子夏曰：「百工居肆以成其事，君子学以致其道」——百工居于作坊以成其事，君子则由学以致其道。"},{id:"ba",label:"八、小人之过也必文",showLabel:!0,sentences:[["子夏曰：“小人之过也必",{text:"文",glossary:"wen-shi"},"。”"]],note:"子夏曰：「小人之过也必文」——小人有过，必加文饰（掩饰）。"},{id:"jiu",label:"九、君子有三变",showLabel:!0,sentences:[["子夏曰：“君子有三变：望之",{text:"俨然",glossary:"yanran"},"，即之也温，听其言也厉。”"]],note:"子夏曰：「君子有三变：望之俨然，即之也温，听其言也厉」——君子有三变：远望庄重俨然，接近则温和，听其言则严谨。"},{id:"shi",label:"十、君子信而后劳其民",showLabel:!0,sentences:[["子夏曰：“君子信而后劳其民，未信，则以为厉己也；信而后谏，未信，则以为谤己也。”"]],note:"子夏曰：「君子信而后劳其民，未信，则以为厉己也；信而后谏，未信，则以为谤己也」——君子先取信而后劳民；未信而劳，则民以为虐己；先取信而后进谏；未信而谏，则君以为谤己。"},{id:"shiyi",label:"十一、大德不逾闲",showLabel:!0,sentences:[["子夏曰：“大德不",{text:"逾闲",glossary:"yuxian"},"，小德出入可也。”"]],note:"子夏曰：「大德不逾闲，小德出入可也」——大节不越界限（闲＝栏，界限），小节稍有出入可以。"},{id:"shier",label:"十二、孰先传焉？孰后倦焉",showLabel:!0,sentences:[["子游曰：“子夏之门人小子，当洒扫应对进退则可矣。抑末也，本之则无，如之何？”子夏闻之，曰：“噫，言游过矣！君子之道，孰先传焉？孰后倦焉？譬诸草木，区以别矣。君子之道焉可诬也？有始有卒者，其惟圣人乎！”"]],note:"子游曰：「子夏之门人小子，当洒扫应对进退则可矣。抑末也，本之则无，如之何」——子夏门人小子，为洒扫应对进退则可，然此皆末节，本则无之，奈何？子夏闻之曰：「噫，言游过矣！君子之道，孰先传焉？孰后倦焉？譬诸草木，区以别矣。君子之道焉可诬也？有始有卒者，其惟圣人乎」——唉，言游错了！君子之道，孰先传、孰后诲？譬如草木，当区以别之；君子之道岂可诬枉？有始有卒、本末兼备者，其唯圣人乎！"},{id:"shisan",label:"十三、仕而优则学，学而优则仕",showLabel:!0,sentences:[["子夏曰：“仕而优则学，学而优则仕。”"]],note:"子夏曰：「仕而优则学，学而优则仕」——仕而有余力则学，学而有余力则仕。"},{id:"shisi",label:"十四、丧致乎哀而止",showLabel:!0,sentences:[["子游曰：“丧致乎哀而止。”"]],note:"子游曰：「丧致乎哀而止」——居丧，致其哀而止。"},{id:"shiwu",label:"十五、吾友张也为难能也",showLabel:!0,sentences:[["子游曰：“吾友张也为难能也，然而未仁。”"]],note:"子游曰：「吾友张也为难能也，然而未仁」——吾友子张难能可贵，然而未仁。"},{id:"shiliu",label:"十六、堂堂乎张也",showLabel:!0,sentences:[["曾子曰：“堂堂乎张也，难与并为仁矣。”"]],note:"曾子曰：「堂堂乎张也，难与并为仁矣」——子张堂堂（高远貌），难与并进于仁。"},{id:"shiqi",label:"十七、人未有自致者也",showLabel:!0,sentences:[["曾子曰：“吾闻诸夫子，人未有自致者也，必也亲丧乎！”"]],note:"曾子曰：「吾闻诸夫子：人未有自致者也，必也亲丧乎」——吾闻于夫子：人未有能自尽其极者，若有，其惟亲丧乎！"},{id:"shiba",label:"十八、孟庄子之孝也",showLabel:!0,sentences:[["曾子曰：“吾闻诸夫子，孟庄子之孝也，其他可能也；其不改父之臣与父之政，是难能也。”"]],note:"曾子曰：「吾闻诸夫子：孟庄子之孝也，其他可能也；其不改父之臣与父之政，是难能也」——孟庄子之孝，其他皆可能；其不改父之臣与父之政，是难能也。"},{id:"shijiu",label:"十九、哀矜而勿喜",showLabel:!0,sentences:[["孟氏使阳肤为士师，问于曾子。曾子曰：“上失其道，民散久矣。如得其情，则",{text:"哀矜",glossary:"aijin"},"而勿喜！”"]],note:"孟氏使阳肤为士师，问于曾子。曾子曰：「上失其道，民散久矣。如得其情，则哀矜而勿喜」——在上者失道，民散已久；若得其情实，当哀矜而勿喜。"},{id:"ershi",label:"二十、君子恶居下流",showLabel:!0,sentences:[["子贡曰：“纣之不善，不如是之甚也。是以君子恶居下流，天下之恶皆归焉。”"]],note:"子贡曰：「纣之不善，不如是之甚也。是以君子恶居下流，天下之恶皆归焉」——纣之不善，不如传说之甚；故君子恶居下流（恶名所归之地），天下之恶皆归之。"},{id:"ershiyi",label:"二十一、君子之过也，如日月之食焉",showLabel:!0,sentences:[["子贡曰：“君子之过也，如日月之食焉。过也，人皆见之；更也，人皆仰之。”"]],note:"子贡曰：「君子之过也，如日月之食焉。过也，人皆见之；更也，人皆仰之」——君子之过，如日月之食：过时人皆见之，改时人皆仰之。"},{id:"ershier",label:"二十二、仲尼焉学",showLabel:!0,sentences:[["卫公孙朝问于子贡曰：“仲尼焉学？”子贡曰：“文武之道未坠于地，在人。贤者识其大者，不贤者识其小者，莫不有文武之道焉，夫子焉不学？而亦何常师之有？”"]],note:"卫公孙朝问于子贡曰：「仲尼焉学」？子贡曰：「文武之道未坠于地，在人。贤者识其大者，不贤者识其小者，莫不有文武之道焉，夫子焉不学？而亦何常师之有」——文武之道未坠于地，仍在人；贤者识其大者，不贤者识其小者，莫不有文武之道；夫子何处不学？又何必有常师？"},{id:"ershisan",label:"二十三、夫子之墙数仞",showLabel:!0,sentences:[["叔孙武叔语大夫于朝曰：“子贡贤于仲尼。”子服景伯以告子贡，子贡曰：“譬之宫墙，赐之墙也及肩，窥见室家之好；夫子之墙数",{text:"仞",glossary:"ren-ren2"},"，不得其门而入，不见宗庙之美、百官之富。得其门者或寡矣，夫子之云不亦宜乎！”"]],note:"叔孙武叔语大夫于朝曰：「子贡贤于仲尼」。子服景伯以告子贡。子贡曰：「譬之宫墙，赐之墙也及肩，窥见室家之好；夫子之墙数仞，不得其门而入，不见宗庙之美、百官之富。得其门者或寡矣，夫子之云不亦宜乎」——譬如宫墙：赐之墙仅及肩，可窥见室家之好；夫子之墙数仞，不得其门而入，则不见宗庙之美、百官之富；得其门者或寡矣，武叔之言不亦宜乎！"},{id:"ershisi",label:"二十四、仲尼不可毁也",showLabel:!0,sentences:[["叔孙武叔毁仲尼，子贡曰：“无以为也，仲尼不可毁也。他人之贤者，丘陵也，犹可逾也；仲尼，日月也，无得而逾焉。人虽欲自绝，其何伤于日月乎？多见其不知量也。”"]],note:"叔孙武叔毁仲尼。子贡曰：「无以为也，仲尼不可毁也。他人之贤者，丘陵也，犹可逾也；仲尼，日月也，无得而逾焉。人虽欲自绝，其何伤于日月乎？多见其不知量也」——勿为此，仲尼不可毁；他人之贤如丘陵，尚可逾；仲尼如日月，不可逾；人虽欲自绝于日月，于日月何伤？只显其不自量耳。"},{id:"ershiwu",label:"二十五、如之何其可及也",showLabel:!0,sentences:[["陈子禽谓子贡曰：“子为恭也，仲尼岂贤于子乎？”子贡曰：“君子一言以为知，一言以为不知，言不可不慎也。夫子之不可及也，犹天之不可",{text:"阶而升",glossary:"jieersheng"},"也。夫子之得邦家者，所谓立之斯立，道之斯行，",{text:"绥之斯来",glossary:"suizhisilai"},"，动之斯和。其生也荣，其死也哀，如之何其可及也？”"]],note:"陈子禽谓子贡曰：「子为恭也，仲尼岂贤于子乎」？子贡曰：「君子一言以为知，一言以为不知，言不可不慎也。夫子之不可及也，犹天之不可阶而升也。夫子之得邦家者，所谓立之斯立，道之斯行，绥之斯来，动之斯和。其生也荣，其死也哀，如之何其可及也」——君子一言而见其智，一言而见其不智，言不可不慎。夫子之不可及，犹天之不可阶而升。夫子若得邦家，则所谓立之斯立、道之斯行、绥之斯来、动之斯和；其生也荣，其死也哀，如何可及！"}],r=[{id:"jiashanerjinneng",term:"嘉善而矜不能",pinyin:"jiā shàn ér jīn bù néng",meaning:"嘉许善者而怜惜能力不足的人。矜：怜悯。"},{id:"ni",term:"泥",pinyin:"nì",meaning:"拘泥、陷住。致远恐泥：要做远大事业，怕被小道拘泥住。"},{id:"qiewenjinsi",term:"切问而近思",pinyin:"qiè wèn ér jìn sī",meaning:"恳切地发问，就切身的问题思考。"},{id:"wen-shi",term:"文",pinyin:"wèn",meaning:"同「纹」，掩饰。小人之过也必文：小人有了过错一定要掩饰。"},{id:"yanran",term:"俨然",pinyin:"yǎn rán",meaning:"庄重严肃的样子。"},{id:"yuxian",term:"逾闲",pinyin:"yú xián",meaning:"越过界限。闲：木栏，引申为界限。"},{id:"aijin",term:"哀矜",pinyin:"āi jīn",meaning:"怜悯、同情。哀矜而勿喜：审案得知实情后应怜悯，不可得意。"},{id:"ren-ren2",term:"仞",pinyin:"rèn",meaning:"古长度单位，七尺（一说八尺）为一仞。数仞：几丈高。"},{id:"jieersheng",term:"阶而升",pinyin:"jiē ér shēng",meaning:"沿着台阶登上去。天之不可阶而升：天不能靠台阶爬上去——喻孔子不可企及。"},{id:"suizhisilai",term:"绥之斯来",pinyin:"suí zhī sī lái",meaning:"绥：安抚。安抚百姓，百姓就会来归附。与「立之斯立」「道之斯行」「动之斯和」同为孔子得位后的效验。"}];return(m,e)=>{const o=n("DaoTextReading"),l=n("DaoKeywordCards");return h(),u("div",null,[e[0]||(e[0]=i('<h1 id="论语·子张" tabindex="-1">论语·子张 <a class="header-anchor" href="#论语·子张" aria-label="Permalink to &quot;论语·子张&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《子张》二十五章，在全书中体例很特别：<strong>通篇没有孔子的话，全是弟子们的言论</strong>。子张、子夏、子游、曾子、子贡——五个人轮番开口，是《论语》中唯一一篇「弟子群像」。</p><p><strong>子张</strong>讲士的操守（见危致命、见得思义），也讲交友之道（尊贤而容众、嘉善而矜不能）。<strong>子夏</strong>的条目最多，几乎句句可传：日知其所亡、博学而笃志切问而近思、百工居肆以成其事、小人之过也必文、君子有三变、大德不逾闲小德出入可也、仕而优则学学而优则仕。<strong>子游</strong>与<strong>曾子</strong>则有对子张的评语（「吾友张也为难能也，然而未仁」「堂堂乎张也」）——<strong>弟子之间也有分歧，且如实记录下来。</strong></p><p><strong>末四章全部属于子贡</strong>，是全篇的高潮。有人问孔子从哪里学来的，子贡答「文武之道未坠于地，在人」；叔孙武叔说子贡比孔子强，子贡以「宫墙」作比（自己的墙只有肩高，老师的墙有几丈）；叔孙武叔毁谤孔子，子贡说「他人之贤者，丘陵也，犹可逾也；仲尼，日月也，无得而逾焉」；最后陈子禽再问，子贡说「夫子之不可及也，犹天之不可阶而升也」。</p><p><strong>《论语》以弟子之口结束，而以子贡护师收束，是极好的安排。</strong></p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',7)),s(o,{colophon:"子张第十九 · 二十五章",tone:"ink",sections:a,glossary:r,"default-mode":"slips","aria-label":"论语·子张 原文"}),e[1]||(e[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),s(l,{items:[{term:"嘉善而矜不能",pinyin:["jiā","shàn","ér","jīn","bù","néng"],meaning:"嘉许善者而怜惜能力不足的人。矜：怜悯。"},{term:"泥",pinyin:["nì"],meaning:"拘泥、陷住。致远恐泥：要做远大事业，怕被小道拘泥住。"},{term:"文",pinyin:["wèn"],meaning:"同「纹」，掩饰。小人之过也必文：小人有了过错一定要掩饰。"},{term:"俨然",pinyin:["yǎn","rán"],meaning:"庄重严肃的样子。"},{term:"逾闲",pinyin:["yú","xián"],meaning:"越过界限。闲：木栏，引申为界限。"},{term:"哀矜",pinyin:["āi","jīn"],meaning:"怜悯、同情。哀矜而勿喜：审案得知实情后应怜悯，不可得意。"},{term:"仞",pinyin:["rèn"],meaning:"古长度单位，七尺（一说八尺）为一仞。数仞：几丈高。"},{term:"阶而升",pinyin:["jiē","ér","shēng"],meaning:"沿着台阶登上去。天之不可阶而升：天不能靠台阶爬上去——喻孔子不可企及。"},{term:"绥之斯来",pinyin:["suí","zhī","sī","lái"],meaning:"绥：安抚。安抚百姓，百姓就会来归附。与「立之斯立」「道之斯行」「动之斯和」同为孔子得位后的效验。"}]}),e[2]||(e[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《子张》二十五章，全由弟子之言构成，可分三段。</p><p><strong>前十三章以子张、子夏为主</strong>。子张讲士的操守与交友（尊贤而容众）；子夏的条目最多，讲为学（日知其所亡、博学笃志切问近思）、讲立身（君子有三变、大德不逾闲）、讲出处（仕而优则学，学而优则仕）。中间夹着子游与子夏关于教学次序的一场争论，也夹着子游、曾子对子张的评语——<strong>弟子之间有分歧，而《论语》照录不讳。</strong></p><p><strong>第十四至二十章以子游、曾子为主</strong>。子游讲丧礼、评子张，曾子讲真情、讲孝、讲断狱之道。第十九章曾子对阳肤说的话极重：<strong>「上失其道，民散久矣。如得其情，则哀矜而勿喜。」</strong>——执法者面对的是失道之世的百姓，审出真相也不可得意。</p><p><strong>末五章全部是子贡</strong>：为纣王辩（「纣之不善，不如是之甚也」）、讲君子之过如日月食、答「仲尼焉学」、三次回护孔子（宫墙、日月、不可阶而升）。<strong>一段弟子群像，最后收在子贡对老师的称扬上。</strong></p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>它对「人」的复杂做了示范</strong>：子游说子张「难能也，然而未仁」，曾子说「堂堂乎张也，难与并为仁矣」——<strong>欣赏一个人的长处，同时说出他的不足</strong>，这才是同门之间的分寸。</li><li><strong>「博学而笃志，切问而近思」是四条极好的治学准则</strong>：学得广、志要定、问得切、想得近——<strong>尤其「近思」二字，把空想拉回自身。</strong></li><li><strong>「大德不逾闲，小德出入可也」给出了一条清晰的边界</strong>：<strong>大节不能错，小节可以灵活。</strong> 这条分寸在做人做事上极为实用。</li><li><strong>「哀矜而勿喜」是执法者的一课</strong>：曾子把「上失其道，民散久矣」当前提——<strong>既然百姓的罪与社会失序有关，审出真相就不该有快感。</strong></li><li><strong>「君子恶居下流」是观察舆论的一把钥匙</strong>：一个人的名声坏到这个程度，往往是「位置」而非「事实」在起作用。<strong>子贡不轻信对纣王的流行评价。</strong></li><li><strong>子贡四章是对「如何评价老师」的最佳示范</strong>：不吹捧，只做比喻——宫墙、丘陵与日月、不可阶而升。<strong>真正的高度，不靠抬高自己，只需把参照物说清楚。</strong></li><li><strong>「其生也荣，其死也哀」把理想的政治评价讲完了</strong>：<strong>活着受人尊敬，死了让人痛惜。</strong> 这比任何政绩指标都更难达到。</li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「切问而近思」检查学习方式</strong>：问题是不是切到要害？思考有没有落在自己能改变的事情上？</li><li><strong>用「大德不逾闲，小德出入可也」处理人际</strong>：底线守死，其余不必斤斤计较。<strong>这能省掉大量无意义的摩擦。</strong></li><li><strong>用「哀矜而勿喜」看待别人的困境</strong>：知道对方的错处时，先想他处在什么环境里。<strong>尤其是手里有权力、有信息优势的时候。</strong></li><li><strong>用「君子之过也，如日月之食焉」看待公开的失误</strong>：错了就是错了，<strong>改正是最有效的弥补</strong>；遮着盖着，反倒像小人「必文」。</li><li><strong>学子贡维护对他人的敬意</strong>：真要推荐或维护一个人，<strong>不必贬低自己，只需把对方的高度说清楚。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《子张》这一篇，孔子一句也没说。说话的全是学生。</p><p>子张讲：读书人该见危致命、见得思义。子夏讲得最多：每天知道自己不知道什么，每个月不忘已经会的；广泛地学，把志向定住，问题要问到点子上，思考要从身边开始；做官有余力就学习，学习有余力就做官。子游和曾子则在评子张——「难能可贵，但还没到仁」「仪表堂堂，却很难和他一起达到仁」。同门之间，欣赏与保留并存。</p><p>这一篇最动人的部分在最后，属于子贡。</p><p>有人质疑孔子没什么了不起，子贡说：拿宫墙比方吧，我的墙只有肩膀高，从外面就能看见里面有房子；我老师的墙几丈高，找不着门进去，就看不见里面的宗庙有多美。能找着门的人很少——所以他说那种话，也不奇怪。</p><p>又有人毁谤孔子，子贡说：别人的贤，像小土丘，还能越过去；我的老师像日月，没法越过。一个人想跟日月断绝关系，对日月有什么损害？</p><p>最后有人说：你只是客气，仲尼哪有你强？子贡说：君子一句话可以显出智慧，一句话也可以显出无知，话不能随便说。<strong>我老师的不可企及，就像天不能靠台阶爬上去。</strong></p><p>——整部《论语》到这里收尾。说这句话的人是子贡，他守了老师一辈子。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「博学而笃志，切问而近思」——我做得最差的是哪一项？学得够广吗？志定得住吗？问得切吗？想得近吗？</li><li>「大德不逾闲，小德出入可也」——我的「大德」是什么？「小德」我又较真到什么程度？</li><li>「哀矜而勿喜」——我在指出别人错误时，有没有一点隐蔽的快意？</li><li>「君子恶居下流」——我是否轻信过对某个人或某个组织的流行评价？</li><li>「其生也荣，其死也哀」——如果用它评价一个人（不必是政治家），我认识谁当得起？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-18">论语·微子</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-20">论语·尧曰</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',25))])}}});export{y as __pageData,w as default};
